from collections import defaultdict

def print_next_greater_freq(arr, n):
    freq = defaultdict(int)
    for num in arr:
        freq[num] += 1

    answer = [-1] * n
    stack = []

    for i in range(n-1, -1, -1):
        current_num = arr[i]
        current_freq = freq[current_num]

        while stack and freq[stack[-1]] <= current_freq:
            stack.pop()

        if stack:
            answer[i] = stack[-1]

        stack.append(current_num)

    return answer
